import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readLandingFile(t){return readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer",t),"utf-8")}describe("Awards of India Explorer Landing Page — Structure",()=>{let t;beforeAll(()=>{t=readLandingFile("index.html")}),it("contains a hero section with title and subtitle",()=>{expect(t).toContain('class="hero-title"'),expect(t).toContain("Awards of India Explorer"),expect(t).toContain("hero-stats")}),it("contains all required award categories in filter buttons",()=>{["Civilian Awards","Gallantry Awards","Sports Awards","Literature &amp; Arts","Science &amp; Technology","National Recognition"].forEach(e=>{expect(t).toContain(e)})}),it("contains search input and category filter buttons",()=>{expect(t).toContain('id="award-search-input"'),expect(t).toContain('class="filter-categories"')}),it("contains award cards with name, category, year, description, and explore button",()=>{expect(t).toContain('class="award-card glass-card"'),expect(t).toContain('class="award-name"'),expect(t).toContain('class="award-category"'),expect(t).toContain('class="award-year"'),expect(t).toContain('class="award-description"'),expect(t).toContain('class="award-btn"')}),it("contains key award cards including Bharat Ratna and Padma awards",()=>{expect(t).toContain("Bharat Ratna"),expect(t).toContain("Padma Vibhushan"),expect(t).toContain("Padma Bhushan"),expect(t).toContain("Padma Shri")}),it("contains an interactive timeline and quiz section",()=>{expect(t).toContain('id="timeline"'),expect(t).toContain('id="quiz"'),expect(t).toContain('id="quiz-container"')}),it("links shared stylesheet, page stylesheet, and script",()=>{expect(t).toContain('href="../../styles.css"'),expect(t).toContain('href="style.css"'),expect(t).toContain('src="script.js"')})}),describe("Awards of India Explorer Landing Page — Assets & Scripts",()=>{it("includes non-empty stylesheet with glassmorphism and responsive styles",()=>{const t=readLandingFile("style.css");expect(t.length).toBeGreaterThan(1e3),expect(t).toContain(".awards-page-body"),expect(t).toContain(".award-card"),expect(t).toContain("@media")}),it("includes interactive script with search, filter, and quiz functions",()=>{const t=readLandingFile("script.js");expect(t.length).toBeGreaterThan(500),expect(t).toContain("initSearchAndFilter"),expect(t).toContain("initQuiz"),expect(t).toContain("quizData")})});